  'about.eyebrow': 'About',
  'about.heroTitle': 'Pixel art, without the friction',
  'about.lead': 'Pixel Art Studio started as a simple idea: a serious pixel editor that opens instantly in a browser tab, with no downloads, accounts or setup. Just open it and draw.',
  'about.para2': 'Most pixel tools force a choice between “powerful but heavy desktop app” and “toy web drawing pad.” We wanted the middle: a focused, production-style workspace — a tool rail, a real canvas with zoom and pan, a frame and layer timeline, and an inspector for image conversion and exports — all running locally in your browser.',
  'about.para3': 'Everything happens on your machine. Your sprites never leave the page, the editor works offline, and you can export a PNG or a portable project file whenever you like.',
  'about.believeTitle': 'What we believe',
  'about.believeInstantLabel': 'Instant.',
  'about.believeInstantText': 'The best tool is the one already open.',
  'about.believeFocusedLabel': 'Focused.',
  'about.believeFocusedText': 'Pixel art deserves purpose-built controls, not generic brushes.',
  'about.believeYoursLabel': 'Yours.',
  'about.believeYoursText': 'Local-first, exportable, no lock-in.',
  'about.openStudio': 'Open the studio →',
  'about.getInTouch': 'Get in touch',
  'faq.eyebrow': 'FAQ',
  'faq.title': 'Frequently asked questions',
  'faq.lead': 'Everything about using Pixel Art Studio.',
  'faq.stillStuck': 'Still stuck?',
  'faq.contactSupport': 'Contact support',
  'faq.q1': 'Is Pixel Art Studio free?',
  'faq.a1': 'Yes. The full editor — drawing tools, animation, layers, image conversion and export — is free to use in your browser with no account required.',
  'faq.q2': 'Do I need to install anything?',
  'faq.a2': 'No. It runs entirely in the browser. Just open the app and start drawing. It also works offline once loaded.',
  'faq.q3': 'Where are my drawings stored?',
  'faq.a3': 'Everything stays on your device. Nothing is uploaded. Use “Export Project” to save a .pixelart.json file you can reload later, or export a PNG.',
  'faq.q4': 'Can I animate sprites?',
  'faq.a4': 'Yes. There is a frame timeline with per-frame duration, onion skin and live playback, plus a layer timeline for organising your art.',
  'faq.q5': 'Can I turn a photo into pixel art?',
  'faq.a5': 'Yes. The Image Convert panel imports any image and reduces it to a palette, with controls for size, fit, dithering, contrast and sharpening.',
  'faq.q6': 'What can I export?',
  'faq.a6': 'PNG at 1x, PNG scaled to your current zoom, and a full .pixelart.json project containing your workspaces, frames, layers, palette and settings.',
  'faq.q7': 'Which browsers are supported?',
  'faq.a7': 'Any modern browser (Chrome, Edge, Firefox, Safari). The on-screen color picker uses the EyeDropper API where available.',
