  'blogpost.post1.title': 'Getting started with pixel art',
  'blogpost.post1.excerpt':
    'A friendly introduction to drawing your first sprite — canvas size, colours and the handful of tools that matter.',
  'blogpost.post1.body':
    '<p>Pixel art looks intimidating, but it rewards restraint. You only need a small canvas, a few colours and a steady hand. This guide walks you through your very first sprite in Pixel Studio.</p><h2>Start small</h2><p>Begin with a tiny canvas — 16×16 or 32×32. A small grid forces you to suggest shapes with just a few pixels, which is the whole craft. You can always scale up later, but learning to read a sprite at a low resolution teaches you what actually matters.</p><h2>Pick a tight palette</h2><p>Resist the urge to use every colour. Four to eight tones is plenty for a first sprite. Open the <code>Palette</code> panel, choose a base colour, then add one shadow and one highlight. Limited colours read more clearly and look intentional.</p><h2>The tools that matter</h2><p>You will reach for the pencil, the eraser and the fill bucket ninety percent of the time. Press <code>P</code> for the pencil, <code>E</code> for the eraser and <code>B</code> for the bucket. Master those three before exploring anything else.</p><h2>Block, then refine</h2><p>Lay down the silhouette first with a single colour, ignore detail entirely, and only once the shape reads do you add shading. If the silhouette is unclear, no amount of detail will save it.</p><p>That is the whole loop: small canvas, few colours, simple tools, shape before detail. Open the editor and draw something — your first sprite is five minutes away.</p>',

  'blogpost.post2.title': 'Animating sprites frame by frame',
  'blogpost.post2.excerpt':
    'How to bring a static sprite to life with a few frames — timing, onion-skinning and exporting a clean GIF.',
  'blogpost.post2.body':
    '<p>Animation is just a few drawings shown in sequence. With pixel art you rarely need many frames — four to six can carry a convincing walk or idle. Here is how to animate without overthinking it.</p><h2>Add frames</h2><p>Each frame is a snapshot of your sprite in time. Duplicate the current frame, nudge a few pixels, and repeat. Small changes between frames feel smooth; big jumps feel jerky.</p><h2>Use onion-skinning</h2><p>Onion-skinning shows a faint ghost of the previous frame underneath the current one, so you can line up movement precisely. Turn it on before you start tweaking — it is the single biggest quality boost for frame-by-frame work.</p><h2>Mind the timing</h2><p>Frame rate sets the mood. A slow idle might breathe at six frames per second, while a snappy attack wants twelve or more. Preview the loop often and adjust the speed until it feels right rather than chasing a number.</p><h2>Export a clean GIF</h2><p>When the loop reads well, export it as an animated <code>GIF</code>. Keep the palette small so the file stays light, and check that the last frame flows back into the first for a seamless loop.</p><p>Start with a two-frame blink or a bobbing coin. Once you see motion appear from a couple of drawings, you will be hooked.</p>',

  'blogpost.post3.title': 'Turn photos into pixel art',
  'blogpost.post3.excerpt':
    'Use the image converter to pixelate a photo, then clean it up by hand for results that actually look hand-drawn.',
  'blogpost.post3.body':
    '<p>Converting a photo is a fast way to get a base sprite, but the magic is in the cleanup. The tool gives you a starting point; your hand makes it look deliberate.</p><h2>Import and pixelate</h2><p>Open <code>Import / convert image…</code> and drop in a photo. Pick a target resolution — lower means chunkier, more stylised pixels. Start coarse; you can always raise the detail.</p><h2>Extract a palette</h2><p>Photos contain thousands of colours, which never reads as pixel art. Use <code>Extract palette</code> to reduce the image to a handful of tones. A tighter palette instantly makes the result feel hand-made instead of merely downscaled.</p><h2>Clean up by hand</h2><p>This is the important part. Zoom in and fix stray pixels, sharpen edges, and redraw any feature the converter mushed together. Five minutes of manual touch-up separates a real sprite from an obvious filter.</p><h2>Export</h2><p>Once it reads cleanly, export a <code>PNG</code> at whatever scale you need. Keep the original layered project around in case you want to revisit the palette later.</p><p>Treat the converter as a sketch, not a finished drawing, and your photo-to-pixel results will look like art rather than a filter.</p>',

