  'about.eyebrow': 'Giới thiệu',
  'about.heroTitle': 'Pixel art, không rào cản',
  'about.lead': 'Pixel Art Studio bắt đầu từ một ý tưởng đơn giản: một trình chỉnh sửa pixel nghiêm túc mở ngay lập tức trong một tab trình duyệt, không cần tải về, đăng ký tài khoản hay cài đặt. Chỉ cần mở lên và vẽ.',
  'about.para2': 'Hầu hết các công cụ pixel buộc bạn phải chọn giữa “ứng dụng desktop mạnh mẽ nhưng nặng nề” và “bảng vẽ web đồ chơi.” Chúng tôi muốn ở giữa: một không gian làm việc tập trung, theo phong cách sản xuất chuyên nghiệp — một thanh công cụ, một canvas thực sự với thu phóng và di chuyển, một dòng thời gian khung hình và lớp, cùng một bảng kiểm tra để chuyển đổi và xuất ảnh — tất cả chạy cục bộ ngay trong trình duyệt của bạn.',
  'about.para3': 'Mọi thứ diễn ra trên máy của bạn. Các sprite của bạn không bao giờ rời khỏi trang, trình chỉnh sửa hoạt động ngoại tuyến, và bạn có thể xuất một tệp PNG hoặc một tệp dự án di động bất cứ khi nào bạn muốn.',
  'about.believeTitle': 'Điều chúng tôi tin tưởng',
  'about.believeInstantLabel': 'Tức thì.',
  'about.believeInstantText': 'Công cụ tốt nhất là công cụ đã sẵn sàng mở.',
  'about.believeFocusedLabel': 'Tập trung.',
  'about.believeFocusedText': 'Pixel art xứng đáng có những công cụ điều khiển được thiết kế riêng, không phải các loại bút vẽ chung chung.',
  'about.believeYoursLabel': 'Của bạn.',
  'about.believeYoursText': 'Ưu tiên cục bộ, có thể xuất, không ràng buộc.',
  'about.openStudio': 'Mở studio →',
  'about.getInTouch': 'Liên hệ',
  'faq.eyebrow': 'Câu hỏi thường gặp',
  'faq.title': 'Câu hỏi thường gặp',
  'faq.lead': 'Mọi điều về cách dùng Pixel Art Studio.',
  'faq.stillStuck': 'Vẫn chưa giải quyết được?',
  'faq.contactSupport': 'Liên hệ hỗ trợ',
  'faq.q1': 'Pixel Art Studio có miễn phí không?',
  'faq.a1': 'Có. Toàn bộ trình chỉnh sửa — công cụ vẽ, animation, lớp, chuyển đổi ảnh và xuất file — đều miễn phí dùng ngay trên trình duyệt mà không cần tài khoản.',
  'faq.q2': 'Tôi có cần cài đặt gì không?',
  'faq.a2': 'Không. Ứng dụng chạy hoàn toàn trên trình duyệt. Chỉ cần mở app và bắt đầu vẽ. Sau khi tải xong, nó cũng hoạt động ngoại tuyến.',
  'faq.q3': 'Bản vẽ của tôi được lưu ở đâu?',
  'faq.a3': 'Mọi thứ nằm trên thiết bị của bạn. Không có gì được tải lên. Dùng “Export Project” để lưu file .pixelart.json có thể mở lại sau, hoặc xuất ra PNG.',
  'faq.q4': 'Tôi có thể tạo animation cho sprite không?',
  'faq.a4': 'Có. Có dòng thời gian khung hình với thời lượng từng khung, onion skin và phát trực tiếp, cùng dòng thời gian lớp để sắp xếp tác phẩm của bạn.',
  'faq.q5': 'Tôi có thể biến ảnh thành pixel art không?',
  'faq.a5': 'Có. Bảng Image Convert nhập bất kỳ ảnh nào và rút gọn về một bảng màu, với các tùy chỉnh kích thước, cách khớp, dithering, độ tương phản và làm sắc nét.',
  'faq.q6': 'Tôi có thể xuất những gì?',
  'faq.a6': 'PNG ở tỉ lệ 1x, PNG theo mức zoom hiện tại, và một dự án .pixelart.json đầy đủ chứa không gian làm việc, khung hình, lớp, bảng màu và cài đặt của bạn.',
  'faq.q7': 'Những trình duyệt nào được hỗ trợ?',
  'faq.a7': 'Bất kỳ trình duyệt hiện đại nào (Chrome, Edge, Firefox, Safari). Bộ chọn màu trên màn hình dùng EyeDropper API khi có sẵn.',
  'blog.eyebrow': 'Blog',
