  'blog.post.animating-sprites-frame-by-frame.title': 'Tạo hoạt ảnh sprite theo từng khung hình',
  'blog.post.animating-sprites-frame-by-frame.excerpt': 'Dùng dòng thời gian khung hình, onion skin và thời lượng từng khung để biến sprite tĩnh thành chuyển động.',
  'blog.post.turn-photos-into-pixel-art.title': 'Biến ảnh chụp thành pixel art bằng tính năng chuyển đổi ảnh',
  'blog.post.turn-photos-into-pixel-art.excerpt': 'Nhập bất kỳ ảnh nào rồi tinh chỉnh kích thước bảng màu, dithering và độ tương phản để có kết quả pixel sạch sẽ.',
