  'blogpost.post1.title': 'Bắt đầu với pixel art',
  'blogpost.post1.excerpt':
    'Giới thiệu dễ tiếp cận về cách vẽ sprite đầu tiên — kích thước canvas, màu sắc và vài công cụ thật sự quan trọng.',
  'blogpost.post1.body':
    '<p>Pixel art trông có vẻ đáng sợ, nhưng nó tưởng thưởng cho sự tiết chế. Bạn chỉ cần một canvas nhỏ, vài màu và một đôi tay vững vàng. Hướng dẫn này dẫn bạn qua sprite đầu tiên trong Pixel Studio.</p><h2>Bắt đầu nhỏ</h2><p>Hãy bắt đầu với canvas thật nhỏ — 16×16 hoặc 32×32. Lưới nhỏ buộc bạn gợi tả hình dạng chỉ bằng vài pixel, và đó chính là cốt lõi của nghề. Bạn luôn có thể phóng to sau, nhưng học cách đọc một sprite ở độ phân giải thấp sẽ dạy bạn điều gì thực sự quan trọng.</p><h2>Chọn bảng màu gọn</h2><p>Đừng ham dùng mọi màu. Bốn đến tám tông là quá đủ cho sprite đầu tiên. Mở bảng <code>Palette</code>, chọn một màu nền, rồi thêm một màu tối và một màu sáng. Ít màu thì hình đọc rõ hơn và trông có chủ đích hơn.</p><h2>Những công cụ quan trọng</h2><p>Bạn sẽ dùng bút chì, cục tẩy và xô đổ màu tới chín mươi phần trăm thời gian. Nhấn <code>P</code> cho bút chì, <code>E</code> cho cục tẩy và <code>B</code> cho xô đổ. Hãy thành thạo ba thứ đó trước khi khám phá bất cứ thứ gì khác.</p><h2>Dựng khối, rồi tinh chỉnh</h2><p>Đặt phần bóng dáng trước bằng một màu duy nhất, bỏ qua hoàn toàn chi tiết, và chỉ khi hình dạng đã đọc được thì mới thêm đổ bóng. Nếu bóng dáng không rõ ràng, chẳng chi tiết nào cứu nổi nó.</p><p>Toàn bộ vòng lặp chỉ có vậy: canvas nhỏ, ít màu, công cụ đơn giản, hình dạng trước chi tiết. Hãy mở trình chỉnh sửa và vẽ thử gì đó — sprite đầu tiên của bạn chỉ cách đây năm phút.</p>',

  'blogpost.post2.title': 'Tạo chuyển động cho sprite từng khung hình',
  'blogpost.post2.excerpt':
    'Cách thổi hồn vào một sprite tĩnh bằng vài khung hình — nhịp độ, onion-skinning và xuất một file GIF gọn gàng.',
  'blogpost.post2.body':
    '<p>Chuyển động chỉ là vài bản vẽ được trình chiếu theo trình tự. Với pixel art bạn hiếm khi cần nhiều khung hình — bốn đến sáu là đủ tải một bước đi hay một tư thế đứng yên thuyết phục. Đây là cách tạo chuyển động mà không nghĩ ngợi quá nhiều.</p><h2>Thêm khung hình</h2><p>Mỗi khung hình là một khoảnh khắc của sprite theo thời gian. Nhân bản khung hình hiện tại, xê dịch vài pixel, rồi lặp lại. Thay đổi nhỏ giữa các khung hình cho cảm giác mượt; nhảy lớn cho cảm giác giật cục.</p><h2>Dùng onion-skinning</h2><p>Onion-skinning hiển thị một bóng mờ của khung hình trước nằm dưới khung hình hiện tại, để bạn căn chỉnh chuyển động chính xác. Hãy bật nó lên trước khi bắt đầu chỉnh — đó là cú nâng chất lượng lớn nhất cho công việc từng khung hình.</p><h2>Chú ý nhịp độ</h2><p>Tốc độ khung hình quyết định tâm trạng. Một tư thế đứng yên chậm có thể thở ở sáu khung hình mỗi giây, trong khi một cú tấn công nhanh cần mười hai hoặc hơn. Hãy xem trước vòng lặp thường xuyên và chỉnh tốc độ cho tới khi thấy hợp lý thay vì chạy theo một con số.</p><h2>Xuất một file GIF gọn gàng</h2><p>Khi vòng lặp đã đọc tốt, hãy xuất nó thành <code>GIF</code> động. Giữ bảng màu nhỏ để file nhẹ, và kiểm tra rằng khung hình cuối nối lại được vào khung hình đầu để có vòng lặp liền mạch.</p><p>Hãy bắt đầu bằng một cái chớp mắt hai khung hình hoặc một đồng xu nhấp nhô. Khi thấy chuyển động hiện ra từ vài bản vẽ, bạn sẽ mê ngay.</p>',

  'blogpost.post3.title': 'Biến ảnh chụp thành pixel art',
  'blogpost.post3.excerpt':
    'Dùng trình chuyển đổi ảnh để pixel hoá một bức ảnh, rồi dọn dẹp bằng tay để có kết quả trông thật sự như vẽ tay.',
  'blogpost.post3.body':
    '<p>Chuyển đổi một bức ảnh là cách nhanh để có sprite nền, nhưng điều kỳ diệu nằm ở khâu dọn dẹp. Công cụ cho bạn điểm khởi đầu; đôi tay của bạn làm nó trông có chủ đích.</p><h2>Nhập và pixel hoá</h2><p>Mở <code>Import / convert image…</code> và thả vào một bức ảnh. Chọn độ phân giải mục tiêu — thấp hơn nghĩa là pixel to bản, cách điệu hơn. Bắt đầu thô; bạn luôn có thể tăng độ chi tiết.</p><h2>Trích xuất bảng màu</h2><p>Ảnh chụp chứa hàng nghìn màu, vốn không bao giờ đọc ra pixel art. Dùng <code>Extract palette</code> để rút ảnh xuống còn một nhúm tông màu. Một bảng màu gọn hơn lập tức khiến kết quả trông như làm bằng tay thay vì chỉ bị thu nhỏ.</p><h2>Dọn dẹp bằng tay</h2><p>Đây là phần quan trọng. Phóng to và sửa các pixel lạc, làm sắc cạnh, và vẽ lại bất kỳ chi tiết nào bị trình chuyển đổi làm nhoè vào nhau. Năm phút chỉnh sửa thủ công tách một sprite thật khỏi một bộ lọc lộ liễu.</p><h2>Xuất file</h2><p>Khi nó đã đọc gọn gàng, hãy xuất một <code>PNG</code> ở tỉ lệ bạn cần. Hãy giữ lại dự án phân lớp gốc phòng khi bạn muốn xem lại bảng màu sau này.</p><p>Hãy xem trình chuyển đổi như một bản phác, không phải bản vẽ hoàn thiện, và kết quả ảnh-thành-pixel của bạn sẽ trông như nghệ thuật chứ không phải một bộ lọc.</p>',

