  'guide.start.heading': 'Bắt đầu',
  'guide.start.p1.a': 'Pixel Art Studio chạy hoàn toàn trong trình duyệt của bạn — không cần cài đặt gì, và tác phẩm của bạn vẫn nằm trên thiết bị của bạn. Mở',
  'guide.start.p1.link': 'trình chỉnh sửa',
  'guide.start.p1.b': ', chọn một công cụ từ thanh bên trái, chọn một màu và bắt đầu vẽ trên canvas ở giữa. Phóng to bằng',
  'guide.start.p1.c': '(hoặc ) và di chuyển bằng cách giữ',
