  'guide.interface.heading': 'Giao diện & bảng điều khiển',
  'guide.interface.intro': 'Không gian làm việc được xây dựng từ các bảng có thể neo, giống như một ứng dụng desktop. Mọi bảng (Tools, Color & Palette, Display, Canvas, Timeline) đều có thể sắp xếp lại:',
  'guide.interface.drag': 'Kéo một bảng bằng thanh tiêu đề của nó để di chuyển giữa các vùng neo trái, phải hoặc dưới, hoặc sắp xếp lại.',
  'guide.interface.tearoff': 'Tách rời một bảng bằng cách kéo nó ra khỏi mọi vùng — nó trở thành một cửa sổ nổi mà bạn có thể di chuyển và thay đổi kích thước, rồi kéo trở lại để neo lại.',
  'guide.interface.headerBtns': 'Dùng các nút trên đầu để thu gọn (▬), nổi (⧉) hoặc đóng (✕) một bảng.',
  'guide.interface.reopen': 'Mở lại các bảng đã đóng từ View ▾; khôi phục tất cả bằng Reset layout.',
