  'guide.interface.commandPalette': 'Command palette — nhấn Ctrl+K để tìm và chạy bất kỳ công cụ hay thao tác nào.',
  'guide.interface.autosave': 'Autosave — toàn bộ dự án của bạn được lưu vào trình duyệt và khôi phục khi tải lại; File ▾ → Start fresh sẽ xóa nó.',
  'guide.interface.minimap': 'Minimap — xuất hiện ở góc dưới bên phải khi phóng to; nhấp/kéo để di chuyển. Brush stabilizer (bảng Tools) làm mượt các nét vẽ tay rung.',
  'guide.interface.colour': 'Colour — Edit ▾ → Adjust colours (sắc độ/độ bão hòa/độ sáng), và Recolor sprite (tab Palette) khớp toàn bộ sprite với bảng màu hiện tại.',
  'guide.interface.note': 'Thanh trên cùng chỉ giữ undo/redo và các menu File, Export và View. Một selection bar bên dưới chứa rotate / flip / copy / cut / paste (chúng tác động lên vùng chọn, hoặc toàn bộ lớp khi không có gì được chọn). Bảng Tools được nhóm thành Draw, Shape và Select, với các tùy chọn brush size, pixel-perfect và symmetry bên dưới.',
  'guide.tools.heading': 'Công cụ',
