  'guide.tool.shade.desc': 'Kéo để làm tối (Alt: làm sáng) dọc theo dải màu của bảng màu.',
  'guide.tool.spray.name': 'Spray',
  'guide.tool.spray.desc': 'Rải các sắc độ của bảng màu quanh màu chính thành các cụm mềm — nước lốm đốm, ánh sáng & bọt nhanh chóng. Size = bán kính; Density & Scatter (kích thước cụm) trong tùy chọn công cụ; tạo vùng chọn để giới hạn.',
  'guide.tool.picker.name': 'Picker',
