  'faq.q1': 'Pixel Art Studio 是免费的吗？',
  'faq.a1': '是的。完整的编辑器——绘图工具、动画、图层、图像转换和导出——都可在浏览器中免费使用，无需账户。',
  'faq.q2': '我需要安装任何东西吗？',
  'faq.a2': '不需要。它完全在浏览器中运行。只需打开应用即可开始绘图。加载后还可离线使用。',
  'faq.q3': '我的绘图存储在哪里？',
  'faq.a3': '一切都保留在你的设备上，不会上传任何内容。使用“Export Project”保存可稍后重新加载的 .pixelart.json 文件，或导出 PNG。',
  'faq.q4': '我可以制作精灵动画吗？',
  'faq.a4': '可以。有带逐帧时长、洋葱皮和实时播放的帧时间轴，以及用于整理作品的图层时间轴。',
  'faq.q5': '我可以把照片变成像素画吗？',
  'faq.a5': '可以。Image Convert 面板可导入任意图像并将其缩减为调色板，提供尺寸、适配、抖动、对比度和锐化等控制。',
  'faq.q6': '我可以导出什么？',
  'faq.a6': '1 倍的 PNG、按当前缩放比例缩放的 PNG，以及包含你的工作区、帧、图层、调色板和设置的完整 .pixelart.json 项目。',
  'faq.q7': '支持哪些浏览器？',
  'faq.a7': '任何现代浏览器（Chrome、Edge、Firefox、Safari）。屏幕取色器在可用时会使用 EyeDropper API。',
