  'blogpost.post1.title': '像素画入门',
  'blogpost.post1.excerpt':
    '一篇友好的入门介绍，带你画出第一个 sprite——画布尺寸、颜色，以及真正重要的几样工具。',
  'blogpost.post1.body':
    '<p>像素画看起来令人生畏，但它奖励克制。你只需要一块小画布、几种颜色和一双稳定的手。本指南将带你在 Pixel Studio 中完成第一个 sprite。</p><h2>从小处着手</h2><p>从极小的画布开始——16×16 或 32×32。小网格迫使你仅用几个像素来暗示形状，而这正是这门手艺的全部。你随时可以放大，但学会在低分辨率下读懂一个 sprite，会教你什么才真正重要。</p><h2>选一组精简的调色板</h2><p>别想着用上每一种颜色。对第一个 sprite 来说，四到八种色调就足够了。打开 <code>Palette</code> 面板，选一个基础色，再加一个阴影色和一个高光色。颜色越少，画面越清晰，看起来也越有意图。</p><h2>真正重要的工具</h2><p>九成的时间你都会用到铅笔、橡皮和油漆桶。按 <code>P</code> 选铅笔，<code>E</code> 选橡皮，<code>B</code> 选油漆桶。先把这三样用熟，再去探索其他任何东西。</p><h2>先铺块，再细化</h2><p>先用单一颜色铺出剪影，完全不管细节，只有当形状能被读懂之后才加阴影。如果剪影本身不清晰，再多的细节也救不了它。</p><p>整个循环就是这样：小画布、少颜色、简单工具、先形状后细节。打开编辑器画点什么吧——你的第一个 sprite 离现在只有五分钟。</p>',

  'blogpost.post2.title': '逐帧制作 sprite 动画',
  'blogpost.post2.excerpt':
    '如何用几帧让一个静态 sprite 活起来——节奏、洋葱皮（onion-skinning）以及导出一个干净的 GIF。',
  'blogpost.post2.body':
    '<p>动画不过是几张依次播放的画。在像素画中你很少需要很多帧——四到六帧就能撑起一段令人信服的行走或待机。下面是不必想太多就能做动画的方法。</p><h2>添加帧</h2><p>每一帧都是 sprite 在某一时刻的快照。复制当前帧，挪动几个像素，然后重复。帧与帧之间的小变化显得流畅；跳得太大就会显得生硬。</p><h2>使用洋葱皮</h2><p>洋葱皮会在当前帧下方显示前一帧的淡淡残影，让你精确对齐动作。在开始微调之前就把它打开——它是逐帧工作中最大的单项质量提升。</p><h2>注意节奏</h2><p>帧率决定情绪。缓慢的待机也许以每秒六帧的节奏呼吸，而干脆利落的攻击则需要十二帧或更多。经常预览循环，调整速度直到感觉对了，而不是去追一个数字。</p><h2>导出干净的 GIF</h2><p>当循环读起来很好时，把它导出为动态 <code>GIF</code>。保持调色板精简以让文件轻巧，并检查最后一帧能否顺畅接回第一帧，形成无缝循环。</p><p>从一个两帧的眨眼或一枚上下浮动的硬币开始吧。一旦你看到动作从寥寥几张画中浮现，你就会上瘾。</p>',

  'blogpost.post3.title': '把照片变成像素画',
  'blogpost.post3.excerpt':
    '用图片转换器把照片像素化，再手动清理，得到真正看起来像手绘的效果。',
  'blogpost.post3.body':
    '<p>转换一张照片是获得基础 sprite 的快捷方式，但魔力在于清理。工具给你一个起点；你的手让它看起来是经过深思熟虑的。</p><h2>导入并像素化</h2><p>打开 <code>Import / convert image…</code>，拖入一张照片。选一个目标分辨率——越低意味着像素越粗、风格化越强。从粗糙开始；你随时可以提高细节。</p><h2>提取调色板</h2><p>照片包含成千上万种颜色，永远不会读起来像像素画。用 <code>Extract palette</code> 把图片缩减到寥寥几种色调。更精简的调色板会立刻让结果显得像手工制作，而非仅仅被缩小。</p><h2>手动清理</h2><p>这是重要的部分。放大并修掉杂散像素、锐化边缘，并重画任何被转换器糊成一团的特征。五分钟的手动润色，就把一个真正的 sprite 与一个一眼可见的滤镜区分开来。</p><h2>导出</h2><p>当它读起来干净后，按你需要的任意比例导出一张 <code>PNG</code>。保留原始的分层项目，以备日后想重新调整调色板。</p><p>把转换器当作草图，而非成品画作，你的照片转像素结果就会看起来像艺术，而不是一个滤镜。</p>',

