  'about.eyebrow': 'À propos',
  'about.heroTitle': 'Le pixel art, sans friction',
  'about.lead': 'Pixel Art Studio est né d\'une idée simple : un véritable éditeur de pixels qui s\'ouvre instantanément dans un onglet de navigateur, sans téléchargement, sans compte ni configuration. Il suffit de l\'ouvrir et de dessiner.',
  'about.para2': 'La plupart des outils de pixels imposent un choix entre une « application de bureau puissante mais lourde » et un « bloc-notes de dessin web jouet ». Nous voulions l\'entre-deux : un espace de travail concentré, de qualité professionnelle — une barre d\'outils, un vrai canevas avec zoom et déplacement, une chronologie d\'images et de calques, et un inspecteur pour la conversion et l\'exportation d\'images — le tout fonctionnant localement dans votre navigateur.',
  'about.para3': 'Tout se passe sur votre machine. Vos sprites ne quittent jamais la page, l\'éditeur fonctionne hors ligne, et vous pouvez exporter un fichier PNG ou un fichier de projet portable quand vous le souhaitez.',
  'about.believeTitle': 'Ce en quoi nous croyons',
  'about.believeInstantLabel': 'Instantané.',
  'about.believeInstantText': 'Le meilleur outil est celui qui est déjà ouvert.',
  'about.believeFocusedLabel': 'Concentré.',
  'about.believeFocusedText': 'Le pixel art mérite des commandes conçues sur mesure, pas des pinceaux génériques.',
  'about.believeYoursLabel': 'À vous.',
  'about.believeYoursText': 'Local d\'abord, exportable, sans verrouillage.',
  'about.openStudio': 'Ouvrir le studio →',
  'about.getInTouch': 'Nous contacter',
  'faq.eyebrow': 'FAQ',
  'faq.title': 'Questions fréquentes',
  'faq.lead': 'Tout sur l\'utilisation de Pixel Art Studio.',
  'faq.stillStuck': 'Toujours bloqué ?',
  'faq.contactSupport': 'Contacter le support',
  'faq.q1': 'Pixel Art Studio est-il gratuit ?',
  'faq.a1': 'Oui. L\'éditeur complet — outils de dessin, animation, calques, conversion et export d\'images — est gratuit dans votre navigateur, sans compte requis.',
  'faq.q2': 'Dois-je installer quelque chose ?',
  'faq.a2': 'Non. Tout fonctionne dans le navigateur. Ouvrez l\'application et commencez à dessiner. Une fois chargée, elle fonctionne aussi hors ligne.',
  'faq.q3': 'Où sont stockés mes dessins ?',
  'faq.a3': 'Tout reste sur votre appareil. Rien n\'est téléversé. Utilisez « Export Project » pour enregistrer un fichier .pixelart.json rechargeable plus tard, ou exportez un PNG.',
  'faq.q4': 'Puis-je animer des sprites ?',
  'faq.a4': 'Oui. Une timeline d\'images avec durée par image, pelure d\'oignon et lecture en direct, ainsi qu\'une timeline de calques pour organiser votre art.',
  'faq.q5': 'Puis-je transformer une photo en pixel art ?',
  'faq.a5': 'Oui. Le panneau Image Convert importe n\'importe quelle image et la réduit à une palette, avec des réglages de taille, d\'ajustement, de tramage, de contraste et de netteté.',
  'faq.q6': 'Que puis-je exporter ?',
  'faq.a6': 'PNG en 1x, PNG mis à l\'échelle de votre zoom actuel, et un projet .pixelart.json complet contenant vos espaces de travail, images, calques, palette et réglages.',
  'faq.q7': 'Quels navigateurs sont pris en charge ?',
  'faq.a7': 'Tout navigateur moderne (Chrome, Edge, Firefox, Safari). Le sélecteur de couleur à l\'écran utilise l\'API EyeDropper lorsqu\'elle est disponible.',
  'blog.eyebrow': 'Blog',
  'blog.heroTitle': 'Tutoriels et astuces',
