  'blogpost.post1.title': 'Débuter en pixel art',
  'blogpost.post1.excerpt':
    'Une introduction accessible pour dessiner votre premier sprite — taille du canevas, couleurs et la poignée d’outils qui comptent.',
  'blogpost.post1.body':
    '<p>Le pixel art a l’air intimidant, mais il récompense la retenue. Il vous suffit d’un petit canevas, de quelques couleurs et d’une main sûre. Ce guide vous accompagne dans votre tout premier sprite avec Pixel Studio.</p><h2>Commencez petit</h2><p>Débutez avec un canevas minuscule — 16×16 ou 32×32. Une petite grille vous oblige à suggérer les formes avec seulement quelques pixels, et c’est là tout le métier. Vous pourrez toujours agrandir plus tard, mais apprendre à lire un sprite en basse résolution vous enseigne ce qui compte réellement.</p><h2>Choisissez une palette serrée</h2><p>Résistez à l’envie d’utiliser toutes les couleurs. Quatre à huit teintes suffisent amplement pour un premier sprite. Ouvrez le panneau <code>Palette</code>, choisissez une couleur de base, puis ajoutez une ombre et une lumière. Des couleurs limitées se lisent plus clairement et paraissent intentionnelles.</p><h2>Les outils qui comptent</h2><p>Vous utiliserez le crayon, la gomme et le pot de peinture quatre-vingt-dix pour cent du temps. Appuyez sur <code>P</code> pour le crayon, <code>E</code> pour la gomme et <code>B</code> pour le pot. Maîtrisez ces trois-là avant d’explorer quoi que ce soit d’autre.</p><h2>Bloquez, puis affinez</h2><p>Posez d’abord la silhouette avec une seule couleur, ignorez totalement les détails, et ce n’est qu’une fois la forme lisible que vous ajoutez l’ombrage. Si la silhouette est confuse, aucun détail ne la sauvera.</p><p>Voilà toute la boucle : petit canevas, peu de couleurs, outils simples, la forme avant le détail. Ouvrez l’éditeur et dessinez quelque chose — votre premier sprite est à cinq minutes d’ici.</p>',

  'blogpost.post2.title': 'Animer des sprites image par image',
  'blogpost.post2.excerpt':
    'Comment donner vie à un sprite statique avec quelques images — le rythme, la pelure d’oignon (onion-skinning) et l’export d’un GIF propre.',
  'blogpost.post2.body':
    '<p>L’animation n’est qu’une suite de dessins montrés dans l’ordre. En pixel art, vous avez rarement besoin de beaucoup d’images — quatre à six peuvent porter une marche ou une pose d’attente convaincante. Voici comment animer sans trop réfléchir.</p><h2>Ajoutez des images</h2><p>Chaque image est un instantané de votre sprite dans le temps. Dupliquez l’image courante, décalez quelques pixels, puis recommencez. De petits changements entre les images donnent une impression de fluidité ; de grands sauts paraissent saccadés.</p><h2>Utilisez la pelure d’oignon</h2><p>La pelure d’oignon affiche un fantôme léger de l’image précédente sous l’image courante, pour aligner le mouvement avec précision. Activez-la avant de commencer vos retouches — c’est le plus grand gain de qualité unique pour le travail image par image.</p><h2>Soignez le rythme</h2><p>La cadence d’images donne le ton. Une pose d’attente lente peut respirer à six images par seconde, tandis qu’une attaque vive en réclame douze ou plus. Prévisualisez souvent la boucle et ajustez la vitesse jusqu’à ce qu’elle semble juste, plutôt que de courir après un chiffre.</p><h2>Exportez un GIF propre</h2><p>Quand la boucle se lit bien, exportez-la en <code>GIF</code> animé. Gardez la palette réduite pour que le fichier reste léger, et vérifiez que la dernière image enchaîne sur la première pour une boucle sans couture.</p><p>Commencez par un clignement d’yeux à deux images ou une pièce qui flotte. Dès que vous verrez le mouvement naître de quelques dessins, vous serez accro.</p>',

  'blogpost.post3.title': 'Transformer des photos en pixel art',
  'blogpost.post3.excerpt':
    'Utilisez le convertisseur d’image pour pixeliser une photo, puis nettoyez-la à la main pour un rendu qui semble vraiment dessiné à la main.',
  'blogpost.post3.body':
    '<p>Convertir une photo est un moyen rapide d’obtenir un sprite de base, mais la magie réside dans le nettoyage. L’outil vous donne un point de départ ; c’est votre main qui le rend délibéré.</p><h2>Importez et pixelisez</h2><p>Ouvrez <code>Import / convert image…</code> et déposez une photo. Choisissez une résolution cible — plus elle est basse, plus les pixels sont gros et stylisés. Commencez grossier ; vous pourrez toujours augmenter le détail.</p><h2>Extrayez une palette</h2><p>Les photos contiennent des milliers de couleurs, ce qui ne se lit jamais comme du pixel art. Utilisez <code>Extract palette</code> pour réduire l’image à une poignée de teintes. Une palette plus serrée fait instantanément paraître le résultat fait main plutôt que simplement réduit.</p><h2>Nettoyez à la main</h2><p>C’est la partie importante. Zoomez et corrigez les pixels parasites, affinez les contours et redessinez tout détail que le convertisseur a écrasé. Cinq minutes de retouche manuelle séparent un vrai sprite d’un filtre évident.</p><h2>Exportez</h2><p>Une fois la lecture nette, exportez un <code>PNG</code> à l’échelle dont vous avez besoin. Conservez le projet d’origine en calques au cas où vous voudriez revoir la palette plus tard.</p><p>Traitez le convertisseur comme une esquisse, pas comme un dessin fini, et vos résultats photo-vers-pixel ressembleront à de l’art plutôt qu’à un filtre.</p>',

