  'guide.start.p1.b': ', choisissez un outil dans la barre de gauche, choisissez une couleur et commencez à dessiner sur le canevas central. Zoomez avec',
  'guide.start.p1.c': '(ou ) et déplacez-vous en maintenant',
  'guide.start.step1': 'Définissez la taille du canevas dans le panneau Canvas (Largeur × Hauteur).',
  'guide.start.step2': 'Dessinez avec le Pen ; remplissez les zones avec Fill.',
