  'contact.smallTeam': 'Мы небольшая команда и читаем каждое сообщение.',
  'about.eyebrow': 'О нас',
  'about.heroTitle': 'Пиксель-арт без лишних преград',
  'about.lead': 'Pixel Art Studio начинался с простой идеи: серьёзный пиксельный редактор, который мгновенно открывается во вкладке браузера, без загрузок, аккаунтов и настройки. Просто откройте и рисуйте.',
  'about.para2': 'Большинство пиксельных инструментов навязывают выбор между «мощным, но тяжёлым настольным приложением» и «игрушечным веб-блокнотом для рисования». Нам хотелось золотой середины: сфокусированное рабочее пространство профессионального уровня — панель инструментов, настоящий холст с масштабированием и панорамированием, шкала кадров и слоёв, а также инспектор для конвертации и экспорта изображений — всё это работает локально в вашем браузере.',
  'about.para3': 'Всё происходит на вашем устройстве. Ваши спрайты никогда не покидают страницу, редактор работает офлайн, и вы можете экспортировать PNG или переносимый файл проекта в любой момент.',
  'about.believeTitle': 'Во что мы верим',
  'about.believeInstantLabel': 'Мгновенно.',
  'about.believeInstantText': 'Лучший инструмент — тот, что уже открыт.',
  'about.believeFocusedLabel': 'Сфокусированно.',
  'about.believeFocusedText': 'Пиксель-арт заслуживает специально созданных инструментов, а не универсальных кистей.',
  'about.believeYoursLabel': 'Ваше.',
  'about.believeYoursText': 'Локально в первую очередь, с возможностью экспорта, без привязки.',
  'about.openStudio': 'Открыть студию →',
  'about.getInTouch': 'Связаться с нами',
  'faq.eyebrow': 'Вопросы и ответы',
  'faq.title': 'Часто задаваемые вопросы',
  'faq.lead': 'Всё об использовании Pixel Art Studio.',
  'faq.stillStuck': 'Остались вопросы?',
  'faq.contactSupport': 'Связаться с поддержкой',
  'faq.q1': 'Pixel Art Studio бесплатный?',
  'faq.a1': 'Да. Полноценный редактор — инструменты рисования, анимация, слои, конвертация изображений и экспорт — бесплатен прямо в браузере, без регистрации.',
  'faq.q2': 'Нужно ли что-то устанавливать?',
  'faq.a2': 'Нет. Всё работает прямо в браузере. Просто откройте приложение и начните рисовать. После загрузки оно работает и офлайн.',
  'faq.q3': 'Где хранятся мои рисунки?',
  'faq.a3': 'Всё остаётся на вашем устройстве. Ничего не загружается. Используйте «Export Project», чтобы сохранить файл .pixelart.json для последующей загрузки, или экспортируйте PNG.',
  'faq.q4': 'Можно ли анимировать спрайты?',
  'faq.a4': 'Да. Есть таймлайн кадров с длительностью каждого кадра, режимом «луковой кожи» и живым воспроизведением, а также таймлайн слоёв для организации работы.',
  'faq.q5': 'Можно ли превратить фото в пиксель-арт?',
  'faq.a5': 'Да. Панель Image Convert импортирует любое изображение и сводит его к палитре, с настройками размера, вписывания, дизеринга, контраста и резкости.',
  'faq.q6': 'Что можно экспортировать?',
  'faq.a6': 'PNG в масштабе 1x, PNG в текущем масштабе и полный проект .pixelart.json со всеми рабочими пространствами, кадрами, слоями, палитрой и настройками.',
  'faq.q7': 'Какие браузеры поддерживаются?',
  'faq.a7': 'Любой современный браузер (Chrome, Edge, Firefox, Safari). Экранная пипетка использует EyeDropper API, где он доступен.',
