  'guide.interface.drag': 'Перетащите панель за её заголовок, чтобы переместить её между левой, правой или нижней зонами стыковки или изменить порядок.',
  'guide.interface.tearoff': 'Открепите панель, перетащив её из любой зоны — она станет плавающим окном, которое можно перемещать и менять в размере, затем перетащите обратно для повторной стыковки.',
  'guide.interface.headerBtns': 'Используйте кнопки заголовка, чтобы свернуть (▬), сделать плавающей (⧉) или закрыть (✕) панель.',
  'guide.interface.reopen': 'Заново откройте закрытые панели через View ▾; восстановите всё с помощью Reset layout.',
