  'guide.interface.commandPalette': 'Command palette — нажмите Ctrl+K, чтобы найти и запустить любой инструмент или действие.',
  'guide.interface.autosave': 'Autosave — весь проект сохраняется в браузере и восстанавливается при перезагрузке; File ▾ → Start fresh очищает его.',
  'guide.interface.minimap': 'Minimap — появляется внизу справа при увеличении; нажмите/перетащите для панорамирования. Brush stabilizer (панель Tools) сглаживает дрожащие штрихи от руки.',
  'guide.interface.colour': 'Colour — Edit ▾ → Adjust colours (тон/насыщенность/яркость), а Recolor sprite (вкладка Palette) приводит весь спрайт к текущей палитре.',
  'guide.interface.note': 'Верхняя панель содержит только отмену/повтор и меню File, Export и View. Расположенная под ней selection bar содержит rotate / flip / copy / cut / paste (они действуют на выделение или на весь слой, если ничего не выделено). Панель Tools сгруппирована в Draw, Shape и Select, а под ней — параметры brush size, pixel-perfect и symmetry.',
  'guide.tools.heading': 'Инструменты',
  'guide.tools.intro': 'Выбирайте инструменты в панели Tools или с помощью горячей клавиши.',
  'guide.tools.colKey': 'Клавиша',
  'guide.tools.colTool': 'Инструмент',
  'guide.tools.colDesc': 'Что делает',
  'guide.tool.pen.name': 'Pen',
  'guide.tool.pen.desc': 'Рисует отдельные пиксели основным цветом.',
  'guide.tool.eraser.name': 'Eraser',
  'guide.tool.eraser.desc': 'Стирает пиксели до прозрачности.',
  'guide.tool.fill.name': 'Fill',
  'guide.tool.fill.desc': 'Заливает связанную область.',
  'guide.tool.gradient.name': 'Gradient',
  'guide.tool.gradient.desc': 'Перетащите от основного к дополнительному; линейный/радиальный с Bayer dither.',
  'guide.tool.shade.name': 'Shade',
  'guide.tool.shade.desc': 'Перетащите для затемнения (Alt: осветление) вдоль рампы палитры.',
  'guide.tool.spray.name': 'Spray',
  'guide.tool.spray.desc': 'Разбрасывает оттенки палитры вокруг основного цвета мягкими скоплениями — быстрая пёстрая вода, свет и пена. Size = радиус; Density и Scatter (размер скопления) в параметрах инструмента; создайте выделение, чтобы ограничить его.',
  'guide.tool.picker.name': 'Picker',
  'guide.tool.picker.desc': 'Берёт образец цвета с холста.',
  'guide.tool.line.name': 'Line',
